
@font-face{font-family:'Cardo';font-style:italic;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}
@font-face{font-family:'Cardo';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}
@font-face{font-family:'Cardo';font-style:normal;font-weight:700;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}
@font-face{font-family:'Cinzel';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}
@font-face{font-family:'Cinzel';font-style:normal;font-weight:600;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}
@font-face{font-family:'Lato';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}
@font-face{font-family:'Lato';font-style:normal;font-weight:700;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}

:root{
  --bg:#ffffff; --bg-soft:#f7f6f1; --ink:#343434; --ink-soft:#585856; --nav:#6b6b6b; --faint:#8c8c86;
  --line:#e9e8e2; --line-2:#dddcd4; --gold:#a07837; --gold-2:#b98f45; --on-gold:#ffffff;
  --display:'Cinzel',Georgia,'Times New Roman',serif;
  --serif:'Cardo',Georgia,'Times New Roman',serif;
  --sans:'Lato','Helvetica Neue',Helvetica,Arial,sans-serif;
  --sh:0 1px 2px rgba(40,40,32,.03),0 16px 40px rgba(40,40,32,.06);
  --sh-lg:0 2px 8px rgba(40,40,32,.05),0 34px 74px rgba(40,40,32,.10);
  --wht:255,255,255;
  --walk:url(data:image/webp;base64,);
}

:root[data-mode="dark"]{--bg:#191917;--bg-soft:#211f1c;--ink:#ebe9e3;--ink-soft:#b6b3ab;--nav:#9a968c;--faint:#75726a;--line:#302e2a;--line-2:#3c3a35;--gold:#cbaa5e;--gold-2:#b3924a;--on-gold:#191917;--wht:25,25,23}
:root[data-mode="dark"] .ph,:root[data-mode="dark"] .figure .ph,:root[data-mode="dark"] .vcard .ph{filter:brightness(.9)}
:root[data-mode="dark"] .brand-logo{filter:brightness(1.06)}
:root[data-mode="dark"] .hnow-status .dot{background:#d9694f}
body{transition:background-color .45s ease,color .45s ease}
.modes{position:fixed;right:12px;bottom:46px;z-index:150;display:flex;background:rgba(var(--wht),.93);backdrop-filter:blur(10px);border:1px solid var(--line)}
.modes button{font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--nav);background:transparent;border:0;padding:7px 12px;cursor:pointer;transition:color .25s,background .25s}
.modes button:hover{color:var(--ink)}
.modes button[aria-current="true"]{background:var(--ink);color:var(--bg)}
@media (max-width:640px){.modes{bottom:auto;top:8px;right:8px}}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
body{margin:0;background:var(--bg);color:var(--ink-soft);font-family:var(--sans);font-weight:400;font-size:17px;line-height:1.75;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;overflow-x:hidden}
.wrap{max-width:1140px;margin:0 auto;padding:0 36px}
h1,h2,h3{font-family:var(--serif);font-weight:400;color:var(--ink);letter-spacing:.01em}
a{color:inherit;text-decoration:none}
img{max-width:100%}
:focus-visible{outline:1px solid var(--gold);outline-offset:4px}
.grain{display:none}
.eyebrow{font-family:var(--sans);font-size:12px;font-weight:700;letter-spacing:.22em;text-transform:uppercase;color:var(--gold);margin:0}

/* header — white, gold logo, grey Lato nav */
header.site{position:fixed;top:0;left:0;right:0;z-index:100;transition:background .5s ease,border-color .5s,box-shadow .5s;border-bottom:1px solid transparent}
body.scrolled header.site{background:rgba(var(--wht),.9);backdrop-filter:blur(14px) saturate(1.05);border-bottom-color:var(--line);box-shadow:0 8px 30px rgba(40,40,32,.05)}
.nav{display:flex;align-items:center;height:70px;gap:30px;transition:height .4s ease}
body.scrolled .nav{height:58px}
.brand{display:flex;align-items:center;order:-1;margin-right:auto}
.brand-logo{height:52px;width:auto;display:block;transition:height .4s ease,filter .4s ease}
body.scrolled .brand-logo{height:40px}
.menu{display:flex;gap:30px;align-items:center}
.menu-left{justify-content:flex-start}
.menu-right{justify-content:flex-end}
.menu a{font-family:var(--sans);font-size:13px;font-weight:700;letter-spacing:.13em;text-transform:uppercase;color:var(--nav);position:relative;padding:8px 0;transition:color .3s}
.menu a:hover{color:var(--gold)}
.menu a::after{content:"";position:absolute;left:0;right:100%;bottom:0;height:1px;background:var(--gold);transition:right .35s ease}
.menu a:hover::after{right:0}
.menu a.dana{color:var(--gold)}
.menu a.dana:hover{color:var(--gold-2)}
.actions{display:flex;align-items:center;gap:14px}
.btn{font-family:var(--sans);font-size:12px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;padding:13px 26px;border:1px solid;border-radius:0;cursor:pointer;transition:all .3s ease;white-space:nowrap;background:transparent}
.btn.ghost{color:var(--ink);border-color:var(--line-2)}
.btn.ghost:hover{border-color:var(--gold);color:var(--gold)}
.btn.solid{background:var(--gold);color:var(--on-gold);border-color:var(--gold)}
.btn.solid:hover{filter:brightness(.9)}
.hamb{display:none;width:46px;height:42px;border:1px solid var(--line-2);border-radius:0;background:transparent;color:var(--ink);cursor:pointer;align-items:center;justify-content:center}
.hamb svg{width:20px;height:20px}
.mpanel{display:none;position:fixed;top:122px;left:0;right:0;z-index:99;background:rgba(var(--wht),.98);backdrop-filter:blur(14px);border-bottom:1px solid var(--line)}
.mpanel a{display:block;padding:16px 36px;border-top:1px solid var(--line);font-family:var(--sans);font-size:13px;font-weight:700;letter-spacing:.13em;text-transform:uppercase;color:var(--nav)}

/* hero — pale, ethereal, Cinzel wordmark */
.hero{position:relative;min-height:94svh;display:flex;align-items:flex-end;overflow:hidden}
.hero-media{position:absolute;inset:0;z-index:0;background-size:cover;background-position:center 42%;filter:saturate(1.05) contrast(1.03)}
#heroMedia.ph{background-position:center 15%}
.hero-scrim{position:absolute;inset:0;z-index:1;background:
  linear-gradient(180deg, rgba(var(--wht),.62) 0%, rgba(var(--wht),.16) 15%, rgba(var(--wht),0) 32%, rgba(var(--wht),0) 50%, rgba(var(--wht),.34) 66%, rgba(var(--wht),.85) 85%, rgba(var(--wht),.98) 100%)}
.hero-inner{position:absolute;left:0;right:0;bottom:0;z-index:3;width:100%;max-width:none;margin:0;padding:0 0 196px 14px;text-align:left}
.hero .eyebrow{display:none}
.hero .eyebrow::after{content:"";display:block;width:44px;height:1px;background:var(--gold);opacity:.6;margin:16px auto 0}
.hero h1{font-family:var(--display);font-weight:400;text-transform:uppercase;font-size:clamp(38px,6.4vw,88px);line-height:1.08;letter-spacing:.1em;color:#3a3a38;margin:0}
.hero .tag{display:none}
.hero-cta{display:flex;flex-wrap:wrap;gap:10px;margin-top:26px;justify-content:flex-start}
.hero .btn{font-size:10px;letter-spacing:.1em;padding:7px 12px}
.hero .btn.ghost{background:rgba(var(--wht),.66);backdrop-filter:blur(4px)}
.hero .btn.ghost:hover{background:rgba(var(--wht),.8)}
.scrollcue{display:none}
.scrollcue span{font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:.26em;text-transform:uppercase}
.scrollcue i{width:1px;height:50px;background:linear-gradient(var(--gold-2),transparent);display:block}

.enter{opacity:1}
body.js .enter{opacity:0;transform:translateY(22px)}
body.js.loaded .enter{opacity:1;transform:none;transition:opacity 1.3s ease,transform 1.3s ease}
body.js.loaded .d1{transition-delay:.1s}body.js.loaded .d2{transition-delay:.34s}
body.js.loaded .d3{transition-delay:.58s}body.js.loaded .d4{transition-delay:.82s}
.reveal{opacity:1;transform:none}
body.js .reveal{opacity:0;transform:translateY(20px)}
body.js .reveal.in{opacity:1;transform:none;transition:opacity 1s ease,transform 1s ease}
@media (prefers-reduced-motion:reduce){body.js .enter,body.js .reveal{opacity:1;transform:none;transition:none}}

/* sections */
section{position:relative;padding:clamp(88px,13vw,180px) 0}
.kicker{margin:0 0 22px}
h2{font-family:var(--serif);font-weight:400;font-size:clamp(30px,4.4vw,52px);line-height:1.12;letter-spacing:.01em;margin:0;max-width:17ch}
.lead{font-family:var(--serif);font-size:clamp(18px,1.9vw,21px);line-height:1.7;color:var(--ink-soft);max-width:60ch;margin:24px 0 0}
.alt{background:var(--bg-soft)}

/* mission */
.mission{display:grid;grid-template-columns:1.1fr .9fr;gap:clamp(44px,7vw,100px);align-items:center}
.figure{position:relative}
.figure .ph{width:100%;aspect-ratio:4/5;box-shadow:var(--sh-lg)}
.mission .figure .ph{aspect-ratio:5/6}
.figure figcaption{font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:.13em;text-transform:uppercase;color:var(--faint);margin-top:16px;display:flex;gap:11px;align-items:baseline}
.figure figcaption::before{content:"";width:26px;height:1px;background:var(--gold);display:inline-block;transform:translateY(-3px)}
.stats{display:flex;gap:clamp(30px,5vw,66px);margin-top:56px;padding-top:40px;border-top:1px solid var(--line)}
.stat .n{font-family:var(--display);font-size:clamp(38px,4.4vw,56px);line-height:1;color:var(--gold);letter-spacing:.02em}
.stat .l{font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:.13em;text-transform:uppercase;color:var(--faint);margin-top:14px;max-width:16ch}

/* schedule */
.sched{list-style:none;margin:48px 0 0;padding:0;border-top:1px solid var(--line-2)}
.sched li{display:grid;grid-template-columns:220px 1fr auto;gap:24px;align-items:baseline;padding:28px 4px;border-bottom:1px solid var(--line);transition:background .35s}
.sched li:hover{background:var(--bg-soft)}
.sched .when{font-family:var(--sans);font-size:12px;font-weight:700;letter-spacing:.13em;text-transform:uppercase;color:var(--gold)}
.sched .when b{display:block;font-family:var(--serif);font-size:22px;font-weight:400;letter-spacing:.01em;text-transform:none;color:var(--ink);margin-bottom:6px}
.sched .ti{font-family:var(--serif);font-size:clamp(19px,2.1vw,24px);color:var(--ink)}
.sched .mo{font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--faint);text-align:right;white-space:nowrap}
.sched-note{margin-top:28px;font-family:var(--serif);font-style:italic;color:var(--ink-soft);font-size:18px}
.sched-note a{color:var(--gold);border-bottom:1px solid rgba(160,120,55,.4)}

/* watch */
.videos{display:grid;grid-template-columns:1.7fr 1fr;gap:20px;margin-top:48px}
.vsmall{display:grid;gap:20px}
.vcard{position:relative;overflow:hidden;box-shadow:var(--sh);cursor:pointer;background:#eceae4}
.vcard .ph{width:100%;height:100%;position:absolute;inset:0;transition:transform .8s ease}
.vcard:hover .ph{transform:scale(1.04)}
.vbig{aspect-ratio:16/10}
.vsmall .vcard{aspect-ratio:16/9}
.vcard .vscrim{position:absolute;inset:0;background:linear-gradient(to top,rgba(30,26,18,.6),rgba(30,26,18,0) 60%)}
.play{position:absolute;left:28px;bottom:66px;width:56px;height:56px;border-radius:50%;border:1px solid rgba(255,255,255,.9);display:flex;align-items:center;justify-content:center;transition:background .3s,border-color .3s}
.vcard:hover .play{background:var(--gold);border-color:var(--gold)}
.play::after{content:"";border-left:15px solid #fff;border-top:10px solid transparent;border-bottom:10px solid transparent;margin-left:4px}
.vsmall .play{width:44px;height:44px;left:22px;bottom:48px}
.vsmall .play::after{border-left-width:12px;border-top-width:8px;border-bottom-width:8px}
.vmeta{position:absolute;left:28px;right:22px;bottom:22px;color:#fff}
.vsmall .vmeta{left:22px;bottom:16px}
.vmeta .s{font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#e8cf97}
.vmeta h3{font-family:var(--serif);font-weight:400;color:#fff;font-size:clamp(18px,2vw,24px);margin:8px 0 0;line-height:1.25}
.vsmall .vmeta h3{font-size:16px}
.watch-actions{display:flex;flex-wrap:wrap;gap:16px;margin-top:36px}


/* video library — shelves, thumbs, select, load-more, modal */
.vselect{font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--nav);background:var(--bg);border:1px solid var(--line-2);border-radius:0;padding:8px 10px;cursor:pointer}
.vspacer{flex:1 1 auto;min-width:10px}
.vitem{background:none;border:0;padding:0;margin:0;text-align:left;font:inherit;color:inherit;cursor:pointer;display:flex;flex-direction:column;width:100%}
.vthumb img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;border:0;transition:transform .6s ease}
.vitem:hover .vthumb img{transform:scale(1.05)}
.vthumb img.noimg{opacity:0}
.vshelf{margin-bottom:46px}
.vshelf-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-bottom:16px}
.vshelf-head h3{font-family:var(--serif);font-weight:400;font-size:clamp(20px,2.2vw,26px);color:var(--ink);margin:0}
.vshelf-all{font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--gold);background:none;border:0;cursor:pointer;white-space:nowrap}
.vshelf-all:hover{color:var(--ink)}
.vrow{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(258px,258px);gap:20px;overflow-x:auto;padding-bottom:10px;scroll-snap-type:x proximity}
.vrow .vitem{scroll-snap-align:start}
.vmore{display:block;margin:36px auto 0;font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--ink);background:transparent;border:1px solid var(--line-2);padding:13px 28px;cursor:pointer}
.vmore:hover{border-color:var(--gold);color:var(--gold)}
.vmodal{position:fixed;inset:0;z-index:300;display:flex;align-items:center;justify-content:center}
.vmodal[hidden]{display:none}
.vmodal-bg{position:absolute;inset:0;background:rgba(8,8,6,.88);backdrop-filter:blur(5px)}
.vmodal-box{position:relative;z-index:1;width:min(980px,92vw)}
.vmodal-player{position:relative;aspect-ratio:16/9;background:#000;box-shadow:var(--sh-lg)}
.vmodal-player iframe{position:absolute;inset:0;width:100%;height:100%;border:0}
.vmodal-bar{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-top:14px;color:#f4f2ea}
.vmodal-title{font-family:var(--serif);font-size:clamp(16px,1.9vw,20px);line-height:1.3}
.vmodal-yt{font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#e8cf97;white-space:nowrap;border:1px solid rgba(232,207,151,.5);padding:10px 15px}
.vmodal-yt:hover{background:rgba(232,207,151,.14)}
.vmodal-x{position:absolute;top:-46px;right:0;width:38px;height:38px;background:none;border:0;color:#fff;font-size:32px;line-height:1;cursor:pointer;opacity:.85}
.vmodal-x:hover{opacity:1}
.ph-walking{background-image:var(--walk)}
#watch{position:relative;isolation:isolate}
#watch::before{content:"";position:absolute;inset:0;z-index:-1;background-image:linear-gradient(180deg,rgba(var(--wht),.8),rgba(var(--wht),.9) 58%,rgba(var(--wht),.95)),var(--walk);background-size:cover;background-position:center 26%;background-attachment:fixed}
@media(max-width:760px){#watch::before{background-attachment:scroll}}
@media(max-width:560px){.vrow{grid-auto-columns:minmax(80vw,80vw)}}

/* Watch — searchable video library */
.vlib{margin-top:44px}
.vlib-controls{display:flex;flex-direction:column;gap:18px;margin-bottom:40px}
.vsearch{position:relative;max-width:520px}
.vsearch svg{position:absolute;left:14px;top:50%;transform:translateY(-50%);width:18px;height:18px;color:var(--faint)}
.vsearch input{width:100%;font-family:var(--serif);font-size:18px;color:var(--ink);background:var(--bg-soft);border:1px solid var(--line-2);border-radius:0;padding:14px 16px 14px 44px}
.vsearch input::placeholder{color:var(--faint)}
.vsearch input:focus{outline:none;border-color:var(--gold)}
.vfilters{display:flex;flex-direction:column;gap:11px}
.vfrow{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.vflabel{font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--faint);margin-right:4px;width:58px}
.vchip{font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--nav);background:transparent;border:1px solid var(--line-2);border-radius:0;padding:7px 13px;cursor:pointer;transition:all .25s}
.vchip:hover{border-color:var(--gold);color:var(--ink)}
.vchip.on{background:var(--gold);border-color:var(--gold);color:var(--on-gold)}
.vcount{font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--faint);margin-left:auto}
.vgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:30px 24px}
.vitem{display:flex;flex-direction:column;text-decoration:none;color:inherit;cursor:pointer}
.vthumb{position:relative;aspect-ratio:16/9;overflow:hidden;background:#e6e4dd;box-shadow:var(--sh)}
.vthumb .ph{position:absolute;inset:0;transition:transform .6s ease}
.vitem:hover .vthumb .ph{transform:scale(1.05)}
.vplay{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:50px;height:50px;border-radius:50%;border:1px solid rgba(255,255,255,.9);display:flex;align-items:center;justify-content:center;background:rgba(22,19,12,.3);transition:background .25s,border-color .25s}
.vitem:hover .vplay{background:var(--gold);border-color:var(--gold)}
.vplay::after{content:"";border-left:13px solid #fff;border-top:8px solid transparent;border-bottom:8px solid transparent;margin-left:3px}
.vitem:hover .vplay::after{border-left-color:var(--on-gold)}
.vdur{position:absolute;right:8px;bottom:8px;font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:.04em;color:#fff;background:rgba(22,19,12,.75);padding:3px 6px}
.vseries{font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:.13em;text-transform:uppercase;color:var(--gold);margin-top:15px}
.vtitle{font-family:var(--serif);font-size:20px;line-height:1.24;color:var(--ink);margin-top:6px}
.vmeta{font-family:var(--sans);font-size:13px;color:var(--faint);margin-top:7px}
.vempty{margin-top:30px;font-family:var(--serif);font-style:italic;color:var(--ink-soft);font-size:18px}
@media(max-width:900px){.vgrid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:560px){.vgrid{grid-template-columns:1fr}.vflabel{width:auto}}


/* feature bands — light, airy */
.band{position:relative;overflow:hidden;padding:clamp(100px,15vw,200px) 0}
.band .ph{position:absolute;inset:0;z-index:0;background-size:cover;background-position:center}
.band .bscrim{position:absolute;inset:0;z-index:1}
.band.land .ph{background-position:center 46%}
.band.land .bscrim{background:linear-gradient(96deg, rgba(var(--wht),.9) 0%, rgba(var(--wht),.82) 42%, rgba(var(--wht),.5) 74%, rgba(var(--wht),.28) 100%)}
.band.dana .ph{opacity:.12}
.band.dana .bscrim{background:radial-gradient(80% 70% at 50% 0%, rgba(160,120,55,.06), rgba(160,120,55,0) 60%),linear-gradient(180deg, rgba(var(--wht),.9), rgba(247,246,241,.92))}
.band-inner{position:relative;z-index:2;max-width:1140px;margin:0 auto;padding:0 36px;width:100%}
.band .eyebrow{color:var(--gold);margin-bottom:24px}
.pull{font-family:var(--serif);font-weight:400;font-size:clamp(30px,4.4vw,54px);line-height:1.14;letter-spacing:.01em;max-width:19ch;margin:0;color:var(--ink)}
.band.dana .pull{font-style:italic;font-size:clamp(24px,3.4vw,42px);max-width:26ch;text-align:center;margin-inline:auto}
.band.dana .band-inner{text-align:center}
.band .sub{font-family:var(--serif);font-size:clamp(17px,1.8vw,20px);color:var(--ink-soft);max-width:54ch;margin:24px 0 0}
.band-cta{display:flex;flex-wrap:wrap;gap:16px;margin-top:40px}
.band.dana .band-cta{justify-content:center}

/* take part */
.ways{list-style:none;margin:52px 0 0;padding:0;border-top:1px solid var(--line-2)}
.ways li{display:grid;grid-template-columns:40px 220px 1fr auto;gap:26px;align-items:center;padding:30px 4px;border-bottom:1px solid var(--line);transition:background .35s}
.ways li:hover{background:var(--bg-soft)}
.ways .ic{width:28px;height:28px;color:var(--gold)}
.ways h3{font-family:var(--serif);font-weight:400;font-size:clamp(20px,2.1vw,26px);margin:0;color:var(--ink)}
.ways p{margin:0;color:var(--ink-soft);font-size:15px;max-width:46ch}
.ways .go{font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--gold);white-space:nowrap}

/* newsletter */
.sub-sec{text-align:center}
.subform{display:flex;max-width:440px;margin:36px auto 0;border-bottom:1px solid var(--line-2)}
.subform input{flex:1;padding:15px 4px;border:0;background:transparent;font-size:18px;font-family:var(--serif);color:var(--ink)}
.subform input:focus{outline:none}
.subform button{background:transparent;border:0;font-family:var(--sans);font-size:12px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--gold);cursor:pointer;padding:0 8px}
.subnote{font-family:var(--sans);font-size:12px;letter-spacing:.04em;color:var(--faint);margin-top:18px;min-height:1.2em}

/* footer */
footer.site{background:var(--bg-soft);border-top:1px solid var(--line);padding:80px 0 44px}
.foot-top{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:40px}
.foot-brand{display:flex;align-items:center}
.foot-brand .brand-logo{height:46px}
.foot p{color:var(--ink-soft);font-size:15px;max-width:40ch;margin:18px 0 0;font-family:var(--serif)}
.foot h4{font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--faint);margin:0 0 16px}
.foot ul{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:12px}
.foot ul a{color:var(--ink-soft);font-size:14.5px}
.foot ul a:hover{color:var(--gold)}
.socials{display:flex;gap:12px;margin-top:20px}
.socials a{width:38px;height:38px;border:1px solid var(--line-2);display:flex;align-items:center;justify-content:center;color:var(--nav);transition:all .3s}
.socials a:hover{color:var(--gold);border-color:var(--gold)}
.socials svg{width:17px;height:17px}
.colophon{margin-top:60px;padding-top:26px;border-top:1px solid var(--line);display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px;font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--faint)}
.colophon b{color:var(--gold)}

/* mockup badge */
.badge{position:fixed;right:0;bottom:0;z-index:150;background:rgba(var(--wht),.92);backdrop-filter:blur(8px);color:var(--nav);font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;padding:9px 15px;border-top:1px solid var(--line);border-left:1px solid var(--line)}
.badge b{color:var(--gold)}


/* The Stillness Bell — bowl trigger + settings panel */
.mbell-wrap{position:relative;align-self:flex-start;margin-bottom:8px}
.mbell{display:inline-flex;align-items:center;gap:9px;font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:.11em;text-transform:uppercase;color:var(--nav);background:rgba(var(--wht),.94);backdrop-filter:blur(10px);border:1px solid var(--line);border-radius:0;padding:8px 13px 8px 10px;cursor:pointer;transition:color .3s,border-color .3s}
.mbell svg{width:20px;height:20px;color:var(--faint);transition:color .3s,transform .3s;transform-origin:50% 62%}
.mbell.on{color:var(--ink)}
.mbell.on svg{color:var(--gold)}
.mbell.off svg{opacity:.5}
.mbell:hover,.mbell[aria-expanded="true"]{border-color:var(--gold)}
@media (prefers-reduced-motion:no-preference){.mbell.ringing svg{animation:mbell-ring 1.9s ease}}
@keyframes mbell-ring{0%,100%{transform:scale(1)}12%{transform:scale(1.12)}32%{transform:scale(.97)}54%{transform:scale(1.04)}76%{transform:scale(.99)}}
/* panel */
.mbell-panel{position:absolute;left:0;bottom:calc(100% + 6px);width:min(90vw,298px);background:rgba(var(--wht),.975);backdrop-filter:blur(16px);border:1px solid var(--line);box-shadow:0 -8px 40px rgba(0,0,0,.18);padding:15px 15px 16px;z-index:6}
.mbell-panel[hidden]{display:none}
@media (prefers-reduced-motion:no-preference){.mbell-panel{animation:mp-in .18s ease}}
@keyframes mp-in{from{opacity:0;transform:translateY(6px) scale(.98)}to{opacity:1;transform:none}}
.mp-head{font-family:var(--serif);font-size:16px;color:var(--ink);letter-spacing:.01em}
.mp-sub{font-family:var(--sans);font-size:10.5px;line-height:1.5;color:var(--faint);margin:3px 0 13px}
.mp-voices{display:grid;grid-template-columns:1fr 1fr;gap:6px}
.mp-voice{display:flex;align-items:center;gap:7px;font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--nav);background:transparent;border:1px solid var(--line-2);border-radius:0;padding:8px 9px;cursor:pointer;text-align:left;transition:border-color .25s,color .25s}
.mp-voice:hover{border-color:var(--gold)}
.mp-voice .mv-ico{width:17px;height:17px;flex:none;color:var(--faint);transition:color .25s}
.mp-voice[aria-pressed="true"]{color:var(--ink);border-color:var(--gold)}
.mp-voice[aria-pressed="true"] .mv-ico{color:var(--gold)}
.mp-row{display:block;margin-top:13px}
.mp-lab{display:flex;justify-content:space-between;align-items:baseline;font-family:var(--sans);font-size:9.5px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:var(--nav);margin-bottom:7px}
.mp-lab b{font-weight:700;color:var(--gold);letter-spacing:.04em}
.mp-row input[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:2px;background:var(--line-2);outline:none;cursor:pointer;margin:0}
.mp-row input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:15px;height:15px;border-radius:50%;background:var(--gold);border:2px solid rgba(var(--wht),1);box-shadow:0 1px 3px rgba(0,0,0,.28);cursor:pointer}
.mp-row input[type=range]::-moz-range-thumb{width:15px;height:15px;border:2px solid rgba(var(--wht),1);border-radius:50%;background:var(--gold);cursor:pointer}
.mp-note{display:block;font-family:var(--sans);font-size:8.5px;letter-spacing:.03em;color:var(--faint);margin-top:7px}
.mbell-panel{max-height:min(80vh,600px);overflow-y:auto}
.mp-sit{display:flex;align-items:center;justify-content:center;gap:8px;width:100%;margin-top:15px;font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--bg);background:var(--gold);border:1px solid var(--gold);border-radius:0;padding:11px;cursor:pointer;transition:opacity .25s}
.mp-sit:hover{opacity:.85}
/* menu is always inline clicks in the banner — no dropdown; wraps under the logo when narrow */
@media (max-width:900px){
  .nav{flex-wrap:wrap;height:auto;row-gap:2px;padding-top:8px;padding-bottom:8px}
  body.scrolled .nav{height:auto}
  .brand{margin-right:16px}
  .menu-left,.menu-right{flex-wrap:wrap}
  .menu{gap:14px}
  .menu a{font-size:10px;letter-spacing:.07em;padding:3px 0}
}
/* Sit with the bell — shared practice space */
.hall{position:fixed;inset:0;z-index:300;display:flex;align-items:center;justify-content:center;background:radial-gradient(120% 120% at 50% 42%,#1b1b18 0%,#0d0d0c 68%,#050504 100%);color:#eae4d6}
.hall[hidden]{display:none}
@media (prefers-reduced-motion:no-preference){.hall{animation:hall-fade .5s ease}}
@keyframes hall-fade{from{opacity:0}to{opacity:1}}
.hall-inner{text-align:center;padding:24px;max-width:520px}
.hall-bowl{position:relative;width:180px;height:180px;margin:0 auto 30px;display:flex;align-items:center;justify-content:center}
.hall-bowl svg{width:150px;height:150px;color:#caa657;position:relative;z-index:2}
.hall-glow{position:absolute;inset:0;border-radius:50%;border:1px solid rgba(202,166,87,.38);box-shadow:0 0 64px 10px rgba(202,166,87,.14)}
@media (prefers-reduced-motion:no-preference){.hall-glow{animation:hall-breathe 11s ease-in-out infinite}.hall.struck .hall-bowl svg{animation:hall-strike 2.2s ease}}
@keyframes hall-breathe{0%,100%{transform:scale(.82);opacity:.5}50%{transform:scale(1.12);opacity:.95}}
@keyframes hall-strike{0%{transform:scale(1)}10%{transform:scale(1.11)}42%{transform:scale(.99)}100%{transform:scale(1)}}
.hall-title{font-family:var(--serif);font-size:27px;letter-spacing:.02em;color:#f2ecdd}
.hall-sub{font-family:var(--sans);font-size:12px;line-height:1.6;color:#b7ad98;margin:12px auto 0;max-width:360px}
.hall-next{font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:#8f876f;margin-top:26px}
.hall-next b{color:#caa657;font-variant-numeric:tabular-nums}
.hall-x{position:absolute;top:20px;right:22px;width:42px;height:42px;background:transparent;border:1px solid rgba(234,228,214,.25);color:#eae4d6;font-size:15px;line-height:1;cursor:pointer;border-radius:0;transition:border-color .25s,color .25s}
.hall-x:hover{border-color:#caa657;color:#caa657}

/* Here & Now bell — white, gold, squared */
.hnow-wrap{position:fixed;left:0;bottom:0;z-index:150;display:flex;flex-direction:column;align-items:stretch;max-width:min(94vw,392px)}
.hnow-preview{display:flex;flex-wrap:wrap;align-items:center;gap:6px;font-family:var(--sans);font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--faint);background:rgba(var(--wht),.94);backdrop-filter:blur(10px);border:1px solid var(--line);border-bottom:0;padding:8px 12px}
.hnow-preview b{color:var(--nav)}
.hnow-preview button{font:inherit;letter-spacing:.1em;text-transform:uppercase;color:var(--nav);background:transparent;border:1px solid var(--line-2);border-radius:0;padding:3px 8px;cursor:pointer}
.hnow-preview button:hover{border-color:var(--gold);color:var(--gold)}
.hnow{display:flex;align-items:center;gap:15px;background:rgba(var(--wht),.96);backdrop-filter:blur(12px);border:1px solid var(--line-2);border-radius:0;padding:15px 22px 15px 15px;box-shadow:var(--sh-lg);transition:border-color .4s;position:relative}
.hnow-bell{position:relative;width:46px;height:46px;flex:none;display:flex;align-items:center;justify-content:center;border:1px solid var(--line-2);color:var(--gold);transition:background .4s,color .4s,border-color .4s}
.hnow-bell svg{width:25px;height:25px;position:relative;z-index:2}
.ring{position:absolute;inset:-1px;border:1px solid var(--gold);opacity:0;pointer-events:none}
.hnow-text{display:flex;flex-direction:column;min-width:0}
.hnow-title{font-family:var(--display);font-size:14px;letter-spacing:.1em;text-transform:uppercase;color:var(--ink)}
.hnow-status{font-family:var(--sans);font-size:11.5px;letter-spacing:.01em;color:var(--ink-soft);margin-top:4px}
.hnow-status .dot{display:none;width:6px;height:6px;border-radius:50%;background:#b8462f;margin-right:7px;vertical-align:middle}
.hnow-go{margin-left:auto;color:var(--faint);flex:none;font-size:15px}
.hnow.soon .hnow-bell{border-color:var(--gold);color:var(--gold)}
.hnow.live{border-color:var(--gold)}
.hnow.live .hnow-bell{background:var(--gold);border-color:var(--gold);color:#fff}
.hnow.live .hnow-go{color:var(--gold)}
.hnow.live .hnow-status .dot{display:inline-block}
@media (prefers-reduced-motion:no-preference){
  .hnow.live .ring{animation:ring 3s ease-out infinite}
  .hnow.live .ring.r2{animation-delay:1.1s}
  @keyframes ring{0%{opacity:.5;transform:scale(.7)}100%{opacity:0;transform:scale(1.5)}}
}

.ph{background-size:cover;background-position:center;background-repeat:no-repeat}
.ph-forest{background-image:url(data:image/webp;base64,)}
.ph-community{background-image:url(data:image/webp;base64,)}
.ph-alms{background-image:url(data:image/webp;base64,)}

@media (max-width:900px){
  .mission{grid-template-columns:1fr;gap:48px}
  .videos{grid-template-columns:1fr}
  .vsmall{grid-template-columns:1fr 1fr}
  .foot-top{grid-template-columns:1fr 1fr}
  .sched li{grid-template-columns:1fr auto;gap:6px 16px}
  .sched .mo{grid-column:2;grid-row:1}
  .ways li{grid-template-columns:30px 1fr;gap:6px 16px}
  .ways p,.ways .go{grid-column:2}
  .ways .go{margin-top:8px}
}
@media (max-width:640px){
  .actions{display:none}
  .menu{gap:12px}
  .menu a{font-size:10px;letter-spacing:.06em}
  .nav{padding-top:10px;padding-bottom:10px}
  .brand-logo{height:64px}
  .vsmall{grid-template-columns:1fr}
  .foot-top{grid-template-columns:1fr}
  .hnow-wrap{left:0;right:0;bottom:0;max-width:none}
  .badge{display:none}
}

.ph-hero{background-image:url(data:image/webp;base64,)}


/* ---- multi-page additions ---- */
main{display:block}
.menu a[aria-current="page"]{color:var(--gold)}
.menu a[aria-current="page"]::after{right:0}
.phero{position:relative;min-height:56vh;display:flex;align-items:flex-end;overflow:hidden}
.phero-media{position:absolute;inset:0;z-index:0;background-size:cover;background-position:center 42%;filter:saturate(1.05) contrast(1.03)}
.phero-scrim{position:absolute;inset:0;z-index:1;background:linear-gradient(to bottom,rgba(20,20,17,.30),rgba(20,20,17,.05) 32%,rgba(20,20,17,.42))}
.phero-inner{position:relative;z-index:2;width:100%;max-width:1140px;margin:0 auto;padding:0 36px 54px;text-align:center;color:#fff}
.phero-inner .eyebrow{color:#f4e6c9}
.phero-inner h1{font-family:var(--serif);font-weight:400;font-size:clamp(34px,5.4vw,60px);line-height:1.05;margin:.24em 0 .18em;color:#fff}
.phero-sub{font-family:var(--serif);font-style:italic;font-size:clamp(15px,1.8vw,20px);color:#f3ecdf;margin:0 auto;max-width:46ch}
.cards-sec{padding:clamp(46px,7vw,96px) 0}
.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.card{display:flex;flex-direction:column;border:1px solid var(--line);background:rgba(var(--wht),.5);text-decoration:none;color:inherit;transition:border-color .3s,transform .3s,box-shadow .3s;overflow:hidden}
.card:hover{border-color:var(--gold);transform:translateY(-3px);box-shadow:0 14px 40px rgba(40,40,32,.10)}
.card-media{position:relative;height:150px;background-size:cover;background-position:center 44%}
.card-body{padding:20px 22px 22px}
.card-body h3{font-family:var(--serif);font-weight:400;font-size:23px;margin:0 0 7px;color:var(--ink)}
.card-body p{font-family:var(--sans);font-size:13px;line-height:1.55;color:var(--nav);margin:0 0 14px}
.card-body .go{font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--gold)}
@media (max-width:900px){.cards{grid-template-columns:repeat(2,1fr)}}
@media (max-width:600px){.cards{grid-template-columns:1fr}.phero{min-height:46vh}}
